#[test]
fn test_pi_b_frozen_vector() {
    let mut lanes = [Lane::new(0, 0); 128];
    for i in 0..128 {
        lanes[i] = Lane::new(
            (i as u64 + 1).wrapping_mul(0xDEADBEEFCAFEBABE),
            (i as u64 + 1).wrapping_mul(0x0123456789ABCDEF),
        );
    }
    pi_b::pi_b(&mut lanes);
    for i in 0..128 {
        assert_eq!(
            (lanes[i].hi, lanes[i].lo),
            PI_B_FROZEN_OUTPUT[i],
            "Pi_B frozen vector mismatch at lane {}", i
        );
    }
}
